// Motor RAG: Busca de Conhecimento e Diagnóstico Técnico Especializado
const rawMsg = $('Webhook WhatsApp').first()?.json?.body?.data?.message?.conversation || $('Webhook WhatsApp').first()?.json?.body?.data?.message?.extendedTextMessage?.text || $('Webhook WhatsApp').first()?.json?.body?.message || '';
const userMessage = String(rawMsg).toLowerCase();
const remoteJid = $('Webhook WhatsApp').first()?.json?.body?.data?.key?.remoteJid || '';
const telefone = remoteJid.replace('@s.whatsapp.net', '') || $('Webhook WhatsApp').first()?.json?.body?.phone || '';
const instanceName = $('Webhook WhatsApp').first()?.json?.body?.instance || 'suporte-chamados';
const reqData = $('Verifica Requisitante').first()?.json || { existe: false };

// Catálogo RAG Híbrido de Diagnóstico da SMS
const knowledgeBase = [
  {
    id: "KB-SYS-CRITICAL",
    categoria: "Sistemas e Softwares",
    equipamentos: ["Computador", "Windows", "CPU", "Gabinete", "Memória RAM", "SSD", "HD"],
    tags: [
      "tela azul", "blue screen", "bsod", "critical_process_died",
      "kernel_data_inpage_error", "whea_uncorrectable_error", "page_fault_in_nonpaged_area",
      "desliga sozinho", "reiniciando sozinho", "reiniciando em loop", "desligando do nada",
      "travamento total", "travou tudo", "beep continuo"
    ],
    sintoma: "Código de erro grave de sistema (ex: ffx..., 0x...), Tela Azul (BSOD) ou falha física de hardware",
    solucao_nivel_1: "ERRO CRÍTICO IDENTIFICADO: Falha no sistema/hardware que requer visita presencial da equipe técnica. Abertura de chamado direto.",
    tipo: "abertura_direta",
    requer_visita: true,
    urgencia_recomendada: "alta"
  },
  {
    id: "KB-SYS-NIVEL1",
    categoria: "Sistemas e Softwares",
    equipamentos: ["Computador", "Windows", "Sistema", "Software"],
    tags: [
      "0x80070005", "acesso negado", "permissao", "bloqueado", "arquivo em uso",
      "0x0000011b", "fila travada", "spooler", "travando aplicativo", "libreoffice", "word", "excel"
    ],
    sintoma: "Erro de permissão de software, bloqueio temporário ou fila de impressão travada",
    solucao_nivel_1: "1. *Executar como Administrador:* feche o aplicativo, clique com o botão direito no ícone e escolha 'Executar como administrador'.\n2. *Gerenciador de Tarefas:* pressione Ctrl + Shift + Esc e finalize a tarefa travada.\n3. *Reiniciar:* reinicie o computador para limpar arquivos temporários.",
    tipo: "orientar_nivel_1",
    requer_visita: false,
    urgencia_recomendada: "media"
  },
  {
    id: "KB-SIS-ESUS",
    categoria: "Sistemas de Saúde",
    equipamentos: ["PEC e-SUS", "Prontuário Eletrônico", "BPA", "SISREG", "Sistema de Saúde"],
    tags: [
      "esus", "pec", "tela branca", "502", "504", "err_connection", "fora do ar",
      "servidor esus", "sistema travou", "prontuario fora", "sisreg", "bpa"
    ],
    sintoma: "Sistema e-SUS / PEC ou prontuário com erro de conexão ou tela branca",
    solucao_nivel_1: "1. *Limpar Cache:* no navegador, pressione Ctrl + Shift + R para forçar a atualização completa.\n2. *Janela Anônima:* tente acessar em uma aba anônima (Ctrl + Shift + N).\n3. *Reiniciar Navegador:* feche todas as abas do navegador e abra novamente o link do e-SUS.",
    tipo: "orientar_nivel_1",
    requer_visita: false,
    urgencia_recomendada: "alta"
  },
  {
    id: "KB-SIS-TOKEN",
    categoria: "Sistemas de Saúde",
    equipamentos: ["Certificado Digital", "Token A3", "Cartão SUS", "Leitora de Cartão"],
    tags: ["token", "certificado", "leitora", "pin", "assinatura digital", "a3", "safesign", "cartao sus"],
    sintoma: "Certificado Digital A3 ou Token não reconhecido para assinatura médica/enfermagem",
    solucao_nivel_1: "1. *Troque de porta USB:* conecte o Token em uma porta USB traseira direta da CPU.\n2. *Verifique o software:* confira se o ícone do SafeSign/Token na barra do Windows está verde.\n3. *Reinicie o navegador:* feche todas as janelas do navegador e tente assinar novamente.",
    tipo: "orientar_nivel_1",
    requer_visita: false,
    urgencia_recomendada: "media"
  },
  {
    id: "KB-IMP-ETIQUETA",
    categoria: "Impressoras",
    equipamentos: ["Zebra ZD220", "Zebra GC420t", "Elgin L42 Pro", "Impressora de Etiqueta", "Etiqueta", "Zebra", "Elgin"],
    tags: ["etiqueta", "luz vermelha", "travada", "calibracao", "sensor", "termica", "rolo", "piscando", "vermelho", "ribbon"],
    sintoma: "Impressora térmica piscando luz vermelha ou descalibrada",
    solucao_nivel_1: "1. *Desligue a impressora:* no botão liga/desliga traseiro.\n2. *Ajuste os guias:* abra a tampa e certifique-se de que as guias amarelas estão ajustadas na largura da etiqueta sem apertar.\n3. *Feche a tampa:* pressione com as duas mãos até ouvir os 2 cliques laterais.\n4. *Calibre o sensor:* ligue segurando o botão Feed até piscar e solte para puxar as etiquetas.\n5. *Reinicie o spooler:* se não imprimir no Windows, reinicie o spooler de impressão.",
    tipo: "orientar_nivel_1",
    requer_visita: false,
    urgencia_recomendada: "media"
  },
  {
    id: "KB-IMP-LASER",
    categoria: "Impressoras",
    equipamentos: ["Lexmark", "Brother", "HP LaserJet", "Ricoh", "Impressora Laser", "Impressora A4", "Toner"],
    tags: ["papel preso", "papel atolado", "spooler", "nao imprime", "laser", "fila de impressao", "toner", "mancha"],
    sintoma: "Impressora laser travada / Papel preso / Erro no spooler de impressão",
    solucao_nivel_1: "1. *Retire o papel preso:* abra a porta frontal com cuidado e puxe a folha no sentido de saída sem rasgar.\n2. *Verifique a bandeja:* garanta que as folhas não estejam úmidas ou amassadas na bandeja.\n3. *Reinicie o Spooler:* abra 'Serviços' no Windows, localize 'Spooler de Impressão' e clique em *Reiniciar*.",
    tipo: "orientar_nivel_1",
    requer_visita: false,
    urgencia_recomendada: "media"
  },
  {
    id: "KB-RED-CABO",
    categoria: "Rede e Conectividade",
    equipamentos: ["Cabo de Rede", "Switch", "Roteador", "Internet"],
    tags: ["sem internet", "cabo de rede", "desconectado", "rede fora", "caiu internet", "sem conexao", "dns"],
    sintoma: "Cabo de rede desconectado ou computador sem sinal de internet/rede local",
    solucao_nivel_1: "1. *Verifique o cabo de rede:* confira atrás do computador se os LEDs do conector de rede estão acesos ou piscando.\n2. *Reconecte o cabo:* desconecte o plugue RJ45, aguarde 5 segundos e reconecte até ouvir o clique.\n3. *Teste em outros PCs:* verifique se outros computadores da sala também estão sem rede.",
    tipo: "orientar_nivel_1",
    requer_visita: false,
    urgencia_recomendada: "alta"
  },
  {
    id: "KB-HRD-LEITOR",
    categoria: "Hardware e Periféricos",
    equipamentos: ["Leitor de Código de Barras", "Leitor Óptico", "Scanner"],
    tags: ["leitor", "codigo de barras", "bip", "scanner", "receita", "medicamento", "farmacia"],
    sintoma: "Leitor de código de barras não emite feixe de luz ou não lê códigos",
    solucao_nivel_1: "1. *Conexão USB:* conecte em uma porta USB traseira direta da CPU.\n2. *Reset de Fábrica:* escaneie o código de barras 'Factory Reset / Restore Default' no manual rápido.",
    tipo: "orientar_nivel_1",
    requer_visita: false,
    urgencia_recomendada: "baixa"
  },
  {
    id: "KB-HRD-ENERGIA",
    categoria: "Hardware e Periféricos",
    equipamentos: ["Monitor", "Nobreak", "Fonte", "Estabilizador", "Filtro de Linha"],
    tags: ["nao liga", "tela preta", "sem sinal", "fonte queimou", "cheiro de queimado", "estalo", "nobreak apitando"],
    sintoma: "Equipamento não liga, sem sinal no monitor ou nobreak apitando",
    solucao_nivel_1: "1. *Alimentação:* verifique se o botão do Nobreak/Filtro de linha está ligado e com luz verde.\n2. *Cabo de vídeo:* confira se o cabo HDMI/VGA está bem parafusado atrás do monitor e da CPU.\n3. *Drenar energia estática:* desligue da tomada, segure o botão power da CPU por 15 segundos e religue.",
    tipo: "orientar_nivel_1",
    requer_visita: true,
    urgencia_recomendada: "alta"
  }
];

// Detecção de código de erro alfanumérico ou BSOD (ex: ffx0001, 0x80070005, tela azul)
const isErrorCode = /\b(ffx[a-z0-9]+|0x[a-f0-9]+|(?=[a-z]*[0-9])(?=[0-9]*[a-z])[a-z0-9]{6,16}|tela\s*azul|bsod|blue\s*screen)\b/i.test(userMessage);

let hasAnyTagMatchedAcrossKB = false;
for (const item of knowledgeBase) {
  for (const tag of item.tags) {
    if (userMessage.includes(tag)) {
      hasAnyTagMatchedAcrossKB = true;
      break;
    }
  }
}

let matched = [];
for (const item of knowledgeBase) {
  let score = 0;
  let hasSymptomTag = false;

  for (const tag of item.tags) {
    if (userMessage.includes(tag)) {
      score += 6;
      hasSymptomTag = true;
    }
  }
  for (const eq of item.equipamentos) {
    if (userMessage.includes(eq.toLowerCase())) {
      score += 1;
    }
  }

  // Se for código de erro ou BSOD e NÃO houver nenhum procedimento específico cadastrado na KB
  if (isErrorCode && item.id === "KB-SYS-CRITICAL" && !hasAnyTagMatchedAcrossKB) {
    score += 15;
    hasSymptomTag = true;
  }

  // Só consideramos match válido no RAG se houver ao menos um sintoma/tag específico correspondente
  if (score >= 6 && hasSymptomTag) {
    matched.push({ score, ...item });
  }
}

matched.sort((a, b) => b.score - a.score);
const topMatch = matched[0] || null;

return [{
  json: {
    mensagem_original: rawMsg,
    telefone: telefone,
    instance_name: instanceName,
    requisitante_nome: reqData.nome || '',
    requisitante_unidade: reqData.unidade || '',
    requisitante_existe: reqData.existe || false,
    rag_encontrado: topMatch !== null,
    rag_contexto: topMatch ? JSON.stringify(topMatch) : 'Nenhum sintoma ou procedimento específico foi encontrado no catálogo RAG. O usuário precisa detalhar o que está acontecendo.',
    top_match: topMatch,
    is_error_code: isErrorCode
  }
}];

