// Decodifica a resposta da IA e normaliza setor e metadados do solicitante
const rawOutput = $json.output || $json.text || '';
let parsed = {};

try {
  const clean = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  const rag = $('Motor RAG (Busca Manual)').first().json;
  parsed = {
    acao: 'investigar',
    resposta_whatsapp: `Recebi sua mensagem sobre *"${rag.mensagem_original}"*.

Poderia me informar qual o equipamento (ex: Computador, Impressora, Sistema) e mais detalhes do ocorrido para que possamos te ajudar ou registrar o chamado?`,
    problema: rag.mensagem_original,
    categoria: 'Geral',
    equipamento: '',
    urgencia: 'media',
    tentativa_rag: ''
  };
}

const ragData = $('Motor RAG (Busca Manual)').first().json;
const nomeFinal = parsed.nome_capturado || ragData.requisitante_nome || 'Solicitante';
let unidadeFinal = parsed.unidade_capturada || ragData.requisitante_unidade || 'Secretaria de Saúde';
const setorFinal = parsed.setor_capturado || '';

// Se for Secretaria de Saúde e houver setor capturado, anexa na unidade se já não estiver presente
if (setorFinal && /secretaria|sms|sede/i.test(unidadeFinal) && !unidadeFinal.toLowerCase().includes(setorFinal.toLowerCase())) {
  unidadeFinal = `${unidadeFinal} - Setor ${setorFinal}`;
}

return [{
  json: {
    ...parsed,
    telefone: ragData.telefone,
    instance_name: ragData.instance_name || 'suporte-chamados',
    nome: nomeFinal,
    unidade: unidadeFinal,
    setor: setorFinal
  }
}];
